import{_ as e,c as n,o as t,ae as s}from"./chunks/framework.Bw0Gm4PQ.js";const p=JSON.parse('{"title":"Restoring Gold Standard Science","description":"","frontmatter":{"title":"Restoring Gold Standard Science","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/05/restoring-gold-standard-science/","publishDate":"2025-05-23T16:56:55-04:00"},"headers":[],"relativePath":"executive-orders/2025-05-23-restoring-gold-standard-science.md","filePath":"executive-orders/2025-05-23-restoring-gold-standard-science.md"}'),r={name:"executive-orders/2025-05-23-restoring-gold-standard-science.md"};function a(o,i,l,c,d,g){return t(),n("div",null,i[0]||(i[0]=[s('<h1 id="restoring-gold-standard-science" tabindex="-1">Restoring Gold Standard Science <a class="header-anchor" href="#restoring-gold-standard-science" aria-label="Permalink to &quot;Restoring Gold Standard Science&quot;">​</a></h1><p>Published: Friday, May 23, 2025</p><ul><li><p><strong>Background Concerns</strong>:</p><ul><li>Trust in scientists has significantly declined over the past five years.</li><li>Majority of researchers perceive a reproducibility crisis in science, exacerbated by data falsification from leading researchers.</li><li>The Federal Government has contributed to this issue through misleading use of scientific information.</li></ul></li><li><p><strong>Examples of Misleading Scientific Practices</strong>:</p><ul><li><strong>CDC Guidance on Schools</strong>: Issued guidelines that discouraged in-person learning despite evidence supporting safer school openings.</li><li><strong>National Marine Fisheries Service</strong>: Adopted incorrect and extreme assumptions regarding North Atlantic right whale population impacting the lobster fishery.</li><li><strong>RCP 8.5 Usage</strong>: Agencies relied on an unrealistic worst-case climate change scenario, misleading public understanding of risks.</li></ul></li><li><p><strong>Commitment to Scientific Integrity</strong>:</p><ul><li>The current Administration aims to restore confidence in science through rigorous and transparent methodologies.</li><li>Emphasis on reproducibility, unbiased peer review, and transparent communication of scientific data.</li></ul></li><li><p><strong>Definition of Key Terms</strong>:</p><ul><li><strong>Employee</strong>: Defined as per 5 U.S.C. 2105.</li><li><strong>Scientific Information</strong>: Encompasses all factual data and analyses across various scientific disciplines.</li><li><strong>Scientific Misconduct</strong>: Involves fabrication, falsification, or plagiarism in research.</li></ul></li><li><p><strong>Implementation of &quot;Gold Standard Science&quot;</strong>:</p><ul><li>Agencies must develop policies to follow established principles such as transparency, collaboration, and rigorous peer review.</li><li>Specific guidance from the Office of Science and Technology Policy (OSTP) to be issued within 30 days.</li></ul></li><li><p><strong>Mandatory Rules for Agencies</strong>:</p><ul><li>Prohibition of scientific misconduct and reliance on tainted information.</li><li>Agencies required to make significant scientific data publicly available, acknowledging uncertainties in analyses.</li><li>Transparency about assumptions and adherence to quality standards in scientific evaluation.</li></ul></li><li><p><strong>Agency Policy Review</strong>:</p><ul><li>Agencies must reassess and update scientific integrity policies to conform with the new standards.</li><li>Emphasis on open exchanges of ideas and protecting dissenting viewpoints.</li></ul></li><li><p><strong>Enforcement and Compliance</strong>:</p><ul><li>Each agency must establish processes for addressing violations of scientific integrity policies.</li><li>Heads may request waivers for certain requirements for good cause.</li></ul></li><li><p><strong>Exclusions and Limitations</strong>:</p><ul><li>The order does not supersede applicable laws or alter the authority of agency heads.</li><li>No new enforceable rights are created for individuals against the government.</li></ul></li></ul><p>This executive order aims to strengthen scientific integrity within federal agencies, restore public confidence, and ensure that scientific information guides decision-making effectively and transparently.</p><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/05/restoring-gold-standard-science/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/05/restoring-gold-standard-science/</a></p>',5)]))}const f=e(r,[["render",a]]);export{p as __pageData,f as default};
